export const BODY: string = "\n<p>تصویر گھمانا اور پلٹنا دو الگ کام ہیں، مگر دونوں تصویر کی سمت درست کرتے ہیں۔ گھمانا تصویر کو موڑتا ہے، پلٹنا اسے آئینہ بنا دیتا ہے۔</p>\n<p>فون پر لی گئی تصویر اکثر ترچھی نکلتی ہے، سیلفی اکثر الٹی لگتی ہے، اور اسکین شدہ دستاویز اکثر الٹی ہوتی ہے۔ یہ تینوں مسئلے گھمانے اور پلٹنے سے حل ہوتے ہیں۔</p>\n<p>یہ رہنما زاویوں، افقی و عمودی پلٹنے، EXIF سمت، بیچ گھماؤ اور عام غلطیوں کی وضاحت کرتا ہے۔ گھمانے کے لیے <a href=\"/ur/tasveer-ghumayein-ultayein/\">روٹیٹ فلپ امیج</a> استعمال کریں۔</p>\n<h2 id=\"what-rotation-and-flipping-do\">گھماؤ اور پلٹنا اصل میں کیا کرتے ہیں</h2>\n<p>گھماؤ تصویر کے پکسلز کو موڑتا ہے: 90 درجے گھمانے سے سیدھی تصویر چوڑی ہو جاتی ہے، اور چوڑی سیدھی ہو جاتی ہے۔ پلٹنا تصویر کو آئینہ بنا دیتا ہے: بایاں دایاں ہو جاتا ہے۔</p>\n<p>دونوں تصویر کا کوئی حصہ نہیں کاٹتے، پوری تصویر محفوظ رہتی ہے۔ صرف اس کی سمت بدلتی ہے۔</p>\n<p>گھماؤ اور پلٹنا مل کر ہر سمت درست کر سکتے ہیں: الٹی تصویر کو 180 درجے گھمائیں، اور آئینہ دار سیلفی کو افقی پلٹیں۔</p>\n<h2 id=\"why-photos-end-up-sideways\">تصویریں ترچھی کیوں نکلتی ہیں</h2>\n<p>فون کا سینسر ہمیشہ ایک ہی سمت میں تصویر لیتا ہے، اور سمت کا عدد بتاتا ہے کہ اسے کیسے دکھانا ہے۔ جو پروگرام عدد نہیں پڑھتا، وہ تصویر کو ترچھی دکھاتا ہے۔</p>\n<p>کیمرہ پکڑنے کا زاویہ بھی وجہ ہے: فون کو ترچھا پکڑنے سے افق ترچھا نکلتا ہے۔ اسکینر میں کاغذ ترچھا رکھنے سے بھی دستاویز ترچھی نکلتی ہے۔</p>\n<p>ترچھی تصویر خراب نہیں ہوتی، صرف اس کی سمت غلط ہے۔ گھما کر محفوظ کرنے سے وہ ہمیشہ کے لیے ٹھیک ہو جاتی ہے۔</p>\n<h2 id=\"rotation-angles-explained\">گھماؤ کے زاویوں کی وضاحت: 90، 180 اور اپنی مرضی</h2>\n<p>90 درجے گھماؤ سیدھی تصویر کو چوڑا اور چوڑی کو سیدھا کرتا ہے۔ یہ سب سے عام گھماؤ ہے، جو فون کی تصویروں میں استعمال ہوتا ہے۔</p>\n<p>180 درجے گھماؤ الٹی تصویر کو سیدھا کرتا ہے۔ اپنی مرضی کا زاویہ، جیسے 2 یا 3 درجے، ترچھے افق کو سیدھا کرتا ہے۔</p>\n<p>اپنی مرضی کا زاویہ استعمال کرتے وقت کنارے کٹتے ہیں، اس لیے تصویر کو تھوڑا بڑا رکھیں۔ چھوٹا زاویہ بھی بڑا فرق ڈالتا ہے۔</p>\n<h2 id=\"flip-horizontal-vs-vertical\">افقی پلٹنا بمقابلہ عمودی پلٹنا</h2>\n<p>افقی پلٹنا بائیں اور دائیں کو بدل دیتا ہے، جیسے آئینہ۔ یہ سیلفی درست کرنے کے لیے استعمال ہوتا ہے، جس میں متن الٹا نظر آتا ہے۔</p>\n<p>عمودی پلٹنا اوپر اور نیچے کو بدل دیتا ہے، جیسے تصویر کو الٹا کر دیا ہو۔ یہ کم استعمال ہوتا ہے، مگر اسکین شدہ تصویر میں کام آتا ہے۔</p>\n<p>دونوں کو ملانے سے تصویر 180 درجے گھوم جاتی ہے۔ پلٹنے سے پہلے سوچیں کہ کون سی سمت بدلنی ہے۔</p>\n<h2 id=\"exif-orientation-basics\">EXIF سمت: کچھ تصویریں خود کیوں گھوم جاتی ہیں</h2>\n<p>EXIF سمت فائل میں لکھا عدد ہے، جو بتاتا ہے کہ تصویر کو کتنا گھمانا ہے۔ فون پکسلز گھمائے بغیر صرف یہ عدد لکھ دیتا ہے۔</p>\n<p>جو پروگرام عدد پڑھتا ہے، وہ تصویر کو سیدھا دکھاتا ہے۔ جو نہیں پڑھتا، وہ اسے ترچھا دکھاتا ہے۔ یہی وجہ ہے کہ ایک ہی تصویر ایک جگہ سیدھی اور دوسری جگہ ترچھی لگتی ہے۔</p>\n<p>مستقل حل یہ ہے کہ پکسلز کو واقعی گھمائیں اور عدد کو 1 کر دیں۔ اس کے بعد ہر پروگرام تصویر کو سیدھا دکھائے گا۔</p>\n<h2 id=\"formats-and-quality\">فارمیٹ اور معیار: آپ کی فائل کا کیا ہوتا ہے</h2>\n<p>90 درجے گھماؤ JPG میں بغیر نقصان کے ہو سکتا ہے، کیونکہ وہ پکسلز کو دوبارہ لکھے بغیر گھماتا ہے۔ اپنی مرضی کا زاویہ دوبارہ کمپریشن مانگتا ہے، جس سے معیار تھوڑا گرتا ہے۔</p>\n<p>PNG میں گھماؤ بغیر نقصان کے ہوتا ہے، کیونکہ PNG بغیر نقصان کے محفوظ کرتا ہے۔ فارمیٹ وہی رہتا ہے، صرف سمت بدلتی ہے۔</p>\n<p>گھمانے کے بعد فائل کا سائز تقریباً وہی رہتا ہے۔ اگر فائل بہت بڑی ہو گئی ہو تو معیار جانچیں۔</p>\n<h2 id=\"batch-rotation\">بہت سی تصویریں ایک ساتھ گھمانا</h2>\n<p>بیچ میں درجنوں تصویریں ایک ساتھ گھمائی جا سکتی ہیں، جیسے پوری البم کی ترچھی تصویریں۔ سب پر ایک ہی زاویہ لگتا ہے۔</p>\n<p>بیچ گھماؤ اس وقت کام آتا ہے جب سب تصویریں ایک ہی سمت میں ترچھی ہوں۔ اگر ہر تصویر الگ سمت میں ہو تو انہیں الگ الگ گھمائیں۔</p>\n<p>بیچ کا نتیجہ ZIP میں ملتا ہے، جس میں نام وہی رہتے ہیں۔ ZIP کھولنے کے بعد چند تصویریں جانچیں۔</p>\n<h2 id=\"straightening-tilted-photos\">ترچھی تصویر کو کونے کھوئے بغیر سیدھا کرنا</h2>\n<p>ترچھے افق کو سیدھا کرنے کے لیے تصویر کو تھوڑا گھمائیں، جیسے 2 درجے۔ گھمانے سے کونے کٹتے ہیں، اس لیے تصویر کو تھوڑا بڑا رکھیں۔</p>\n<p>کونے بچانے کے لیے گھمانے کے بعد تصویر کو کراپ کریں۔ کراپ سے کٹے ہوئے کونے چھپ جاتے ہیں اور تصویر صاف لگتی ہے۔</p>\n<p>سیدھا کرتے وقت افق کو گرڈ سے ملائیں۔ افق سیدھا ہونا ہی تصویر کو متوازن بناتا ہے۔</p>\n<h2 id=\"fixing-mirrored-selfies\">آئینہ دار سیلفی درست کرنا</h2>\n<p>سیلفی میں فون تصویر کو آئینہ دار بنا دیتا ہے، تاکہ پیش منظر میں آپ خود کو آئینے جیسا دیکھیں۔ اس سے تصویر میں متن الٹا نظر آتا ہے۔</p>\n<p>سیلفی درست کرنے کے لیے اسے افقی سمت میں پلٹیں۔ پلٹنے سے متن سیدھا ہو جاتا ہے اور چہرہ بھی درست لگتا ہے۔</p>\n<p>فون کی سیٹنگ میں آئینہ دار سیلفی بند بھی کی جا سکتی ہے، تاکہ نئی سیلفی سیدھی نکلے۔ پرانی سیلفی کو پلٹ کر درست کریں۔</p>\n<h2 id=\"rotate-vs-crop\">گھمائیں یا کاٹیں: کون سا ٹھیک پہلے آتا ہے</h2>\n<p>پہلے گھمائیں، پھر کاٹیں۔ گھمانے سے تصویر کی شکل بدلتی ہے، اور اس کے بعد کراپ کی حد طے کرنا آسان ہوتا ہے۔</p>\n<p>پہلے کاٹنے سے گھمانے کے بعد کنارے کٹ سکتے ہیں۔ درست ترتیب سے تصویر کا کوئی حصہ ضائع نہیں ہوتا۔</p>\n<p>ترتیب یاد رکھیں: گھمائیں، کاٹیں، ری سائز کریں، کمپریس کریں۔ یہی ایڈیٹنگ کی درست ترتیب ہے۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: آپ کی تصویریں آپ کے آلے پر رہتی ہیں</h2>\n<p>گھماؤ آپ کے براؤزر میں ہوتا ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ نجی تصویروں کے لیے بہت اہم ہے۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی نقل محفوظ نہیں رہتی۔</p>\n<p>لیکن گھمائی گئی تصویر میں میٹا ڈیٹا اب بھی ہو سکتا ہے۔ شیئر کرنے سے پہلے میٹا ڈیٹا بھی جانچیں۔</p>\n<h2 id=\"common-mistakes\">تصویریں گھماتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی گھماؤ اور پلٹنے کو آپس میں بدل دینا ہے۔ گھماؤ تصویر کو موڑتا ہے، پلٹنا اسے آئینہ بناتا ہے۔ غلط انتخاب سے تصویر اور خراب ہو جاتی ہے۔</p>\n<p>دوسری غلطی اصل فائل کو اوور رائٹ کر دینا ہے۔ ہمیشہ اصل محفوظ رکھیں اور گھمائی گئی نقل الگ نام سے محفوظ کریں۔</p>\n<p>تیسری غلطی سمت کا میٹا ڈیٹا چھوڑ دینا ہے۔ گھمانے کے بعد عدد کو 1 کر دیں، ورنہ تصویر دوبارہ ترچھی دکھائی دے سکتی ہے۔</p>\n<h2 id=\"when-to-rotate-vs-reshoot\">گھمائیں یا دوبارہ لیں</h2>\n<p>اگر تصویر صرف ترچھی ہو تو گھمائیں۔ اگر تصویر دھندلی ہو یا روشنی خراب ہو تو دوبارہ لینا بہتر ہے، کیونکہ گھماؤ ان مسئلوں کو ٹھیک نہیں کرتا۔</p>\n<p>دوبارہ لینا اس وقت بھی بہتر ہے جب گھمانے سے اہم حصہ کٹ جائے۔ نئی تصویر لینا کٹے ہوئے حصے کو واپس نہیں لا سکتا، مگر بہتر فریمنگ دے سکتا ہے۔</p>\n<p>فیصلہ کرتے وقت وقت دیکھیں: گھمانا سیکنڈوں کا کام ہے، دوبارہ لینا منٹوں کا۔ اگر گھماؤ کافی ہو تو دوبارہ نہ لیں۔</p>\n<h2 id=\"rotating-scanned-receipts\">اسکین شدہ رسیدیں اور فارم گھمانا</h2>\n<p>اسکین شدہ رسید اکثر ترچھی یا الٹی نکلتی ہے، کیونکہ کاغذ ترچھا رکھا گیا تھا۔ اسے 90 یا 180 درجے گھما کر سیدھا کریں۔</p>\n<p>رسید گھمانے کے بعد متن کو پڑھ کر جانچیں۔ اگر متن سیدھا پڑھا جائے تو گھماؤ درست ہے۔</p>\n<p>رسید کو PDF بنانے سے پہلے گھمائیں، تاکہ PDF میں سب صفحے سیدھے ہوں۔ الٹی PDF پڑھنا مشکل ہوتا ہے۔</p>\n<h2 id=\"rotation-and-printing\">پرنٹ کے لیے تصویریں گھمانا</h2>\n<p>پرنٹ سے پہلے تصویر کی سمت جانچیں، کیونکہ پرنٹر سمت کا میٹا ڈیٹا نظر انداز کر سکتا ہے۔ ترچھی تصویر ترچھی ہی پرنٹ ہو جاتی ہے۔</p>\n<p>پرنٹ کے لیے تصویر کو پکسلز میں گھما کر محفوظ کریں۔ اس کے بعد پرنٹر اسے سیدھا چھاپے گا۔</p>\n<p>پرنٹ سے پہلے تصویر کو کمپیوٹر پر کھول کر دیکھیں۔ اگر وہاں سیدھی لگے تو پرنٹ بھی سیدھا نکلے گا۔</p>\n<h2 id=\"rotation-file-naming\">گھمائی گئی فائلوں کا نام رکھنا اور ترتیب دینا</h2>\n<p>گھمائی گئی فائل کا نام واضح رکھیں، جیسے اصل نام کے ساتھ rotated لکھیں۔ واضح نام اصل اور نقل میں فرق بتاتا ہے۔</p>\n<p>فائلوں کو تاریخ اور مقصد کے مطابق فولڈر میں رکھیں۔ ترتیب سے رکھیں، تاکہ بعد میں تلاش کرنا آسان ہو۔</p>\n<p>اصل فائل کو الگ فولڈر میں رکھیں اور اس پر کبھی براہ راست کام نہ کریں۔</p>\n<h2 id=\"combining-rotation-with-edits\">گھماؤ کو دیگر ایڈٹس کے ساتھ ملانا</h2>\n<p>گھماؤ کو کراپ، فلٹر اور روشنی کی ایڈیٹنگ کے ساتھ ملاتے وقت ترتیب اہم ہے: پہلے گھمائیں، پھر کراپ کریں، پھر فلٹر لگائیں۔</p>\n<p>گھمانے کے بعد تصویر کے ابعاد بدل جاتے ہیں، اس لیے ری سائز گھمانے کے بعد کریں۔ الٹی ترتیب سے تصویر کا سائز غلط ہو جاتا ہے۔</p>\n<p>سب ایڈٹس کے بعد نتیجہ کو مکمل سائز میں دیکھیں۔ اگر سب درست لگے تو محفوظ کریں۔ سمت کی تفصیل <a href=\"/ur/blog/tasveer-orientation-exif-rotation/\">EXIF سمت کی وضاحت</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-kaise-ghumayein-ultayein/\">تصویر کیسے گھمائیں اور پلٹیں</a> میں دیکھیں۔ کراپ کرنا ہو تو <a href=\"/ur/tasveer-crop-karein/\">امیج کراپر</a> استعمال کریں۔</p>\n";

